import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

import { loadDecisions } from './decisions'
import type { Decisions } from './decisions'
import { extractAnimals } from './extract-animals'
import type { AnimalSpecies, AnimalsData } from './extract-animals'
import { GAME_SLICE_DIR, OUTPUT_PATHS } from './paths'

/** Generated files by absolute path, each with its exact content. */
export type CatalogFiles = Readonly<Record<string, string>>

const serialize = (data: unknown): string => `${JSON.stringify(data, null, 2)}\n`

const missing = (what: string, key: string): never => {
  throw new Error(`animals-catalog: no ${what} for "${key}" in decisions.json`)
}

const lookup = (map: Readonly<Record<string, string>>, key: string, what: string): string => map[key] ?? missing(what, key)

const bodyOf = (spec: AnimalsData['specs'][string] | undefined): { kind: string; spec: unknown } => {
  if (!spec) return missing('body spec', 'species')
  if (spec.snake) return { kind: 'snake', spec: {} }
  const raw = spec.q ?? spec.b ?? {}
  const { extra, tex, ...numbers } = raw as Record<string, unknown>
  return { kind: spec.q ? 'quadruped' : 'bird', spec: { ...numbers, ...(tex === undefined ? {} : { texture: tex }), ...(extra === undefined ? {} : { hasExtraBuilder: true }) } }
}

const outcomeOf = (species: AnimalSpecies, decisions: Decisions): string => lookup(decisions.outcomes.value, species.inf, 'outcome')

const outbreakOf = (id: string, outcome: string, decisions: Decisions): unknown => {
  const rule = decisions.outbreak.value
  if (outcome === 'turns') return { turnMinutes: rule.turns.exceptions[id] ?? rule.turns.turnMinutes, ...(id === 'rat' ? { biteInfectionChance: rule.turns.ratBiteInfectionChance } : {}) }
  if (outcome === 'dies') return { deathHours: rule.dies.deathHours, carcass: rule.dies.carcass }
  return undefined
}

export const buildSpecies = (data: AnimalsData, decisions: Decisions): unknown =>
  data.order.map((sourceId, order) => {
    const species = data.species.find((entry) => entry.id === sourceId) ?? missing('species', sourceId)
    const id = lookup(decisions.speciesIds.value, sourceId, 'species id')
    const spec = data.specs[sourceId]
    const body = bodyOf(spec)
    const outcome = outcomeOf(species, decisions)
    const outbreak = outbreakOf(id, outcome, decisions)
    const sound = decisions.soundRanges.value[id]
    return {
      id,
      order,
      name: { en: lookup(decisions.speciesNames.value, id, 'species name'), 'pt-BR': species.nome },
      scientificName: species.sci,
      group: lookup(decisions.groups.value, species.grupo, 'group'),
      phase: lookup(decisions.phases.value, species.fase, 'phase'),
      outcome,
      ...(outbreak === undefined ? {} : { outbreak }),
      ...(sound === undefined ? {} : { soundRangeMetres: sound.metres }),
      body: { kind: body.kind, ...(body.spec as object) },
      walkHz: spec?.walkHz,
      runHz: spec?.runHz,
      ...(spec?.gallop ? { gallop: true } : {}),
    }
  })

export const buildCatalog = (): CatalogFiles => {
  const data = extractAnimals()
  const decisions = loadDecisions()
  return {
    [OUTPUT_PATHS.gaits]: serialize(Object.fromEntries(Object.entries(data.gaits).map(([name, phases]) => [name, phases.map((phase) => Math.round(phase * 1e9) / 1e9)]))),
    [OUTPUT_PATHS.species]: serialize(buildSpecies(data, decisions)),
  }
}

const README = `# Game slice: animals

Generated by \`pnpm --filter @adatechnology/animals-catalog-tool catalog:game\` from Bichos do Vale (spec 001, Phase 4).
**This folder goes to the zombiada repository** (\`content/animals/\`), not to the SDK: it names the valley (where each animal lives, the
terrain of the map). The SDK keeps the generic parts (\`game-animals\`, \`game-animals-species\`).

| File | What | Source |
|---|---|---|
| \`species-texts.json\` | Per species: subtitle, where it lives, role, care, yield, sound (pt-BR) | \`SPECIES\` |
| \`zones.json\` | Where each species is spawned: \`[x, z, radius, place]\` | \`ZONES\` |
| \`terrain.json\` | Rivers, lakes, roads and cities of the map | \`TER\` |
`

export const buildGameSlice = (): CatalogFiles => {
  const data = extractAnimals()
  const decisions = loadDecisions()
  const files: Record<string, string> = {
    'README.md': README,
    'species-texts.json': serialize(
      Object.fromEntries(data.species.map((species) => [lookup(decisions.speciesIds.value, species.id, 'species id'), { subtitle: species.sub, where: species.onde, role: species.papel, care: species.cuidado, yield: species.rende, sound: species.som }])),
    ),
    'zones.json': serialize(Object.fromEntries(Object.entries(data.zones).map(([id, zones]) => [lookup(decisions.speciesIds.value, id, 'species id'), zones]))),
    'terrain.json': serialize(data.terrain),
  }
  return Object.fromEntries(Object.entries(files).map(([name, content]) => [join(GAME_SLICE_DIR, name), content]))
}

export const writeFiles = (files: CatalogFiles): void => {
  for (const [path, content] of Object.entries(files)) {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, content)
  }
}

/** Paths whose file on disk differs from what the sources generate now. */
export const staleFiles = (files: CatalogFiles): string[] =>
  Object.entries(files)
    .filter(([path, content]) => {
      try {
        return readFileSync(path, 'utf8') !== content
      } catch {
        return true
      }
    })
    .map(([path]) => path)
